/**
 * A matemática dos esportes — a mesa de bilhar e a linha de previsão.
 *
 * A cena não recalcula nada: a polilinha vem pronta em `info.caminho`, da mesma
 * `simularBilhar` que escreve a leitura do puzzle. Duas contas separadas fariam
 * a linha desenhada mentir sobre o resultado medido, que é justamente o que o
 * módulo quer mostrar — que dá para PREVER a jogada antes de dar a tacada.
 *
 * O mundo do simulador tem origem no centro da mesa, x para a direita e y para
 * cima; o canvas tem y para baixo. A conversão está num lugar só (`px`/`py`).
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

type Ponto = readonly [number, number];

/** As cores do pano e das esferas: são a cor da coisa, não decisão de tema. */
const PANO = '#1f7a4c';
const PANO_ESCURO = '#17603b';
const ALVO = '#d1332e';
const EM_MOVIMENTO = '#f5c542';

function pontos(bruto: unknown): Ponto[] {
  if (!Array.isArray(bruto)) return [];

  const lista: Ponto[] = [];
  for (const item of bruto) {
    if (!Array.isArray(item)) continue;
    const x = Number(item[0]);
    const y = Number(item[1]);
    if (Number.isFinite(x) && Number.isFinite(y)) lista.push([x, y]);
  }
  return lista;
}

function ponto(bruto: unknown, padrao: Ponto): Ponto {
  const lista = pontos([bruto]);
  return lista[0] ?? padrao;
}

/** Comprimento acumulado de uma polilinha — para animar a esfera sobre ela. */
function percorrer(caminho: readonly Ponto[], fracao: number): Ponto | undefined {
  if (caminho.length === 0) return undefined;

  const trechos: number[] = [];
  let total = 0;
  for (let i = 1; i < caminho.length; i++) {
    const a = caminho[i - 1];
    const b = caminho[i];
    if (a === undefined || b === undefined) continue;
    const d = Math.hypot(b[0] - a[0], b[1] - a[1]);
    trechos.push(d);
    total += d;
  }
  if (total === 0) return caminho[0];

  let restante = total * limitar(fracao, 0, 1);
  for (let i = 0; i < trechos.length; i++) {
    const d = trechos[i] ?? 0;
    const a = caminho[i];
    const b = caminho[i + 1];
    if (a === undefined || b === undefined) continue;
    if (restante <= d || i === trechos.length - 1) {
      const k = d === 0 ? 0 : limitar(restante / d, 0, 1);
      return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k];
    }
    restante -= d;
  }
  return caminho[caminho.length - 1];
}

const bilhar: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const W = numeroDe(info, 'W', 20);
    const H = numeroDe(info, 'H', 12);
    const R = numeroDe(info, 'R', 1.25);
    const caminho = pontos(info.caminho);
    const inicio = ponto(info.start, [W * 0.4, -H * 0.3]);
    const alvo = ponto(info.target, [-W * 0.35, -H * 0.17]);
    const rebotes = Math.trunc(numeroDe(info, 'bounce', -1));
    const angulo = numeroDe(info, 'ang', 0);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Ângulo de entrada = ângulo de saída');

    // ── A mesa ───────────────────────────────────────────────────────────
    const margem = L * 0.06;
    const topo = A * 0.2;
    const disponivelL = L - margem * 2;
    const disponivelA = A * 0.66;
    const escala = Math.min(disponivelL / W, disponivelA / H);
    const larguraMesa = W * escala;
    const alturaMesa = H * escala;
    const ox = (L - larguraMesa) / 2;
    const oy = topo + (disponivelA - alturaMesa) / 2;

    const px = (x: number): number => ox + (x + W / 2) * escala;
    const py = (y: number): number => oy + (H / 2 - y) * escala;

    const borda = Math.max(6, escala * 0.9);
    retangulo(
      ctx,
      ox - borda,
      oy - borda,
      larguraMesa + borda * 2,
      alturaMesa + borda * 2,
      borda,
      MATERIAIS.madeira,
      MATERIAIS.madeiraClara,
      1.5,
    );

    const feltro = ctx.createLinearGradient(0, oy, 0, oy + alturaMesa);
    feltro.addColorStop(0, PANO);
    feltro.addColorStop(1, PANO_ESCURO);
    ctx.fillStyle = feltro;
    ctx.fillRect(ox, oy, larguraMesa, alturaMesa);

    // As cacapas dos quatro cantos, só para a mesa ler como mesa.
    const cacapa = Math.max(4, escala * 0.5);
    for (const [cx, cy] of [
      [ox, oy],
      [ox + larguraMesa, oy],
      [ox, oy + alturaMesa],
      [ox + larguraMesa, oy + alturaMesa],
    ] as const) {
      disco(ctx, cx, cy, cacapa, 'rgb(20 26 40 / 85%)');
    }

    // ── O alvo ───────────────────────────────────────────────────────────
    // Sobre o pano verde, ouro translúcido some. O alvo é uma bola vermelha de
    // verdade, com um anel branco pulsando em volta.
    const raioAlvo = Math.max(5, R * escala);
    const pulso = ok ? 1 : 1 + Math.sin(t * 3) * 0.1;

    disco(ctx, px(alvo[0]) + 1.5, py(alvo[1]) + 2, raioAlvo, 'rgb(20 26 40 / 35%)');
    disco(ctx, px(alvo[0]), py(alvo[1]), raioAlvo, ok ? cor.verde : ALVO);
    disco(
      ctx,
      px(alvo[0]) - raioAlvo * 0.3,
      py(alvo[1]) - raioAlvo * 0.3,
      raioAlvo * 0.26,
      'rgb(255 255 255 / 55%)',
    );

    ctx.strokeStyle = ok ? cor.verde : 'rgb(255 255 255 / 85%)';
    ctx.lineWidth = 1.6;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.arc(px(alvo[0]), py(alvo[1]), raioAlvo * pulso + 5, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // ── A linha de previsão ──────────────────────────────────────────────
    if (caminho.length > 1) {
      ctx.strokeStyle = ok ? cor.verde : 'rgb(255 255 255 / 70%)';
      ctx.lineWidth = ok ? 3 : 2;
      ctx.lineJoin = 'round';
      ctx.setLineDash(ok ? [] : [7, 5]);
      ctx.beginPath();
      for (const [i, p] of caminho.entries()) {
        if (i === 0) ctx.moveTo(px(p[0]), py(p[1]));
        else ctx.lineTo(px(p[0]), py(p[1]));
      }
      ctx.stroke();
      ctx.setLineDash([]);

      // Cada quina da polilinha é uma tabela: marcá-las é mostrar a regra.
      for (const p of caminho.slice(1, -1)) {
        disco(ctx, px(p[0]), py(p[1]), 3.4, ok ? cor.verde : 'rgb(255 255 255 / 85%)');
      }

      // A esfera percorrendo o traçado, num ciclo de 2,4 s. Amarela: branca ela
      // se confundia com a bola parada e com as marcas de tabela.
      const andando = percorrer(caminho, (t / 2.4) % 1);
      if (andando !== undefined) {
        disco(ctx, px(andando[0]), py(andando[1]), Math.max(4, escala * 0.34), EM_MOVIMENTO);
      }
    }

    // ── A esfera na mão, no ponto de partida ─────────────────────────────
    const raioBola = Math.max(5, escala * 0.4);
    disco(ctx, px(inicio[0]) + 1.5, py(inicio[1]) + 2, raioBola, 'rgb(20 26 40 / 35%)');
    disco(ctx, px(inicio[0]), py(inicio[1]), raioBola, cor.contraste);
    disco(
      ctx,
      px(inicio[0]) - raioBola * 0.3,
      py(inicio[1]) - raioBola * 0.3,
      raioBola * 0.3,
      'rgb(255 255 255 / 90%)',
    );

    // O ângulo vai num canto vazio do pano: colado na bola ele disputava lugar
    // com a marca da primeira tabela e com a esfera em movimento.
    const miudo = limitar(A * 0.036, 9, 13);
    etiqueta(
      ctx,
      `tacada ${angulo.toFixed(1).replace('.', ',')}°`,
      ox + 8,
      oy + miudo * 1.6,
      miudo,
      cor.texto,
      700,
      { alinhamento: 'left' },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      rebotes === 0
        ? 'Na bucha, sem tabela ✔'
        : `Encaçapou após ${rebotes} ${rebotes === 1 ? 'tabela' : 'tabelas'} ✔`,
      'Gire o ângulo e siga a linha tracejada até ela cruzar o alvo.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default bilhar;
